# Ajouter EXILLIUM et la rubrique expatriation à l’annuaire
# Fiche, logo, recherche, catégorie, référencement et sitemap.
# Contrôlé à 320, 375 et 1440 pixels ; 4 239 maisons et 17 catégories.
import base64,hashlib,json,pathlib,subprocess,zlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
ENTRIES=[{'path': '_build/logos/dir-meta.json', 'before': '9bef2c761b7d3ff7fe94c00232eb938e17fcc7b0671317503e20041d6118049c', 'after': '921a51c75c728c77099ce08fbb2374e7bcf14f91892c54c39e54ce55dec3b094'}, {'path': 'assets/ecosysteme/maison/app.js', 'before': '1ff2ce82e15b96554d1bea4679fa694280c2f25293d0d915b5afa617f0584f53', 'after': '610138cc409b31b2a80031b88093f068de4727306b75de7eba6858dbaa7af108'}, {'path': 'assets/ecosysteme/maison/data.json', 'before': '7ad7166fbdbaafe86d7123b09423fe2801ea10b84f33c87ccba4b7b7196d7fd7', 'after': '9e91936214823d0873fc51ea176428339599de22039b786b42ead2315a984a27'}, {'path': 'assets/ecosysteme/maison/sources-logos.json', 'before': '0dd94f60f1f1585c2bf3d03a22932e744facf07ae4a854e2cc2b81fe585625ae', 'after': '9e700d2a52061cadb4091cf06bf2aae423bbac45293b44be23685a3e8247926c'}, {'path': 'assets/logos/dir/exillium.png', 'before': None, 'after': '8ea1a9898baba94874939bdcf677ad22c8d34a060de2c8cb30321b3772ab28e1'}, {'path': 'ecosysteme-ligues.html', 'before': 'e98209f13c280c1cc6989168fb9564088a48110d433251dc0bdb4ef718993cb8', 'after': '62cc3b0b300973c26ddf3549dba1d235177711b03f1bbaf947087b2c65069c69'}, {'path': 'ecosysteme.html', 'before': '3870cabd176f1e30e2cd86c8516e9010bc7e7d0daed2cf0dc07d32381caca006', 'after': '28052a2784b27a636ae16cefd5ce783d4fcd181670202604b01a704620683709'}, {'path': 'f/exillium.html', 'before': None, 'after': '0c30db6273b49afd8754472df73292a0ad7a3c0d53c2b77816d8b67ecf47abed'}, {'path': 'referencement.html', 'before': 'cf1100e84325b58d80a90ea21087fc41b5c08fc8e57befdc548bd10f3676d619', 'after': '08d020eb5d6c0046521278c22b5fef7e486ae14894cda3052a567e723091eefe'}, {'path': 'sitemap.xml', 'before': 'e28b4ad2dadcb7ef055909aeb2f120d03027d11e92c26e9dbf58ae07a756234b', 'after': 'c273ade328a43e2f4bdad346f8a56b7a3fe17f2c41902c8a652783a61dd56297'}]
PAYLOAD=""""""
hash_file=lambda p:hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
states=[]
for e in ENTRIES:
    p=(ROOT/e['path']).resolve()
    assert p.is_relative_to(ROOT),e['path']
    states.append(hash_file(p))
if all(s==e['after'] for s,e in zip(states,ENTRIES)):
    print('EXILLIUM déjà intégré ; aucun changement nécessaire.')
else:
    assert all(s==e['before'] for s,e in zip(states,ENTRIES)), 'Fichiers modifiés depuis préparation ; intégration arrêtée avant toute écriture.'
    patch=zlib.decompress(base64.b64decode(PAYLOAD))
    subprocess.run(['git','apply','--check','--binary','--whitespace=nowarn','-'],input=patch,cwd=ROOT,check=True)
    subprocess.run(['git','apply','--binary','--whitespace=nowarn','-'],input=patch,cwd=ROOT,check=True)
    assert all(hash_file(ROOT/e['path'])==e['after'] for e in ENTRIES)
    print('EXILLIUM et rubrique expatriation intégrés ; 10 fichiers vérifiés.')
